include <robotics.scad>
// Feetech SCS0009 case, origin = bottom centre of case, shaft at +X.
L = 23.3;  W = 12.1;  H_body = 21.45;  H_top = 25.25;
tab_L = 32.5; tab_W = 11; tab_z0 = 16.8; tab_z1 = 18.4;
hole_x = 14.25; hole_d = 2;
shaft_x = 5.7;
cap_x0 = -3.75;          // gear-cap end, scaled from side view (not dimensioned)
r = 0.6;                 // small edge break, conservative
$fn = 40;

diff() {
  union() {
    // main body
    translate([0,0,0]) cuboid([L, W, H_body], rounding=r, edges="Z", anchor=BOT);
    // gear cap on the shaft end
    translate([(cap_x0 + L/2)/2, 0, H_body - 0.01])
      cuboid([L/2 - cap_x0, W, H_top - H_body + 0.01], rounding=r, edges="Z", anchor=BOT);
    // mounting tab plate through the case
    translate([0,0,tab_z0]) cuboid([tab_L, tab_W, tab_z1 - tab_z0], rounding=0.5, edges="Z", anchor=BOT);
  }
  tag("remove") xflip_copy() translate([hole_x, 0, tab_z0 - 0.5]) cyl(d=hole_d, h=3, anchor=BOT);
}

include <robotics.scad>
// 20-tooth output spline, origin at top face of case on shaft axis.
OD = 3.95; teeth = 20; h = 3.2; tooth_depth = 0.25;
tap_d = 1.6; tap_depth = 3;
pts = [for (i = [0:teeth*2-1]) let(a = i*180/teeth, rr = (i%2==0) ? OD/2 : OD/2 - tooth_depth) [rr*cos(a), rr*sin(a)]];
difference() {
  translate([0,0,-0.01]) linear_extrude(h + 0.01) polygon(pts);
  translate([0,0,h - tap_depth]) cylinder(d=tap_d, h=tap_depth + 0.1, $fn=24);
}
